    payroll_count_mode,
    minijob_mode,
    bezirk_mode,
    uv_rate,
    employer_name,
    employer_address,
    employer_tax_number,
    monthly_budget,
    account_fee,
    weekly_hours_target,
    private_hours_budget,
    mj_kv_ag,
    mj_rv_ag,
    mj_pauschsteuer,
    mj_u1,
    mj_u2,
    mj_insolvenzgeld,
    mj_rv_an,
  } = body

  if (typeof hourly_rate !== 'number' || hourly_rate <= 0) {
    return NextResponse.json({ error: 'Ungültiger Stundensatz' }, { status: 400 })
  }

  const supabase = await createClient()
