    { label: `Jahr ${year}`, range: yearRange(year) },
    { label: `Jahr ${year - 1}`, range: yearRange(year - 1) },
  ]

  const activePreset = presets.find(
    (p) => p.range.from === currentFrom && p.range.to === currentTo
