function getCombinations(array) {
  let result = [];
  for (let i = 0;i < array.length; i++) {
    let current = array.splice(i, 1);
    let tempArray = array.slice();
    if (array.length > 1) {
      let tempPermutations = getCombinations(tempArray);
      tempPermutations.forEach(permutations => {
        result.push(current.concat(permutations));
      });
    } else {
      result.push(current.concat(array));
    }
    array.splice(i, 0, current[0]);
  }
  return result;
}

