class GameState:
    def __init__(self):
        self.board = [[None, None, None],
                      [None, None, None],
                      [None, None, None]
        ]

    def is_game_over(self):
        b = self.board
        # Check if a player won
        if b[0][0] == b[0][1] == b[0][2] != None or b[1][0] == b[1][1] == b[1][2] != None or b[2][0] == b[2][1] == b[2][2] != None:
            return True
        elif b[0][0] == b[1][0] == b[2][0] != None or b[0][1] == b[1][1] == b[2][1] != None or b[0][2] == b[1][2] == b[2][2] != None:
            return True
        elif b[0][0] == b[1][1] == b[2][2] != None or b[0][2] == b[1][1] == b[2][0] != None:
            return True
        # Check if the board is full
        elif any(None in row for row in b):
            return False
        # All positions filled, no winner
        else:
            return True

# Defining a node 
Node <- function(value){	 
   this$value <- value
   this$next <- NULL
   return(this)
} 

# Defining a Linked List 
LinkedList <- function(){ 
   this$head <- NULL
   this$tail <- NULL

   # Function to add an element in the linked list 
   addNode <- function(value){
        newnode <- Node(value) 

        # If the Linked List has no node 
        if(is.null(this$head)){ 
            this$head <- newnode
            this$tail <- newnode 
        } else { 

            # Point tail node to newly added node
            this$tail$next <- newnode 
            this$tail <- newnode 
        } 

        # Return the new linked list
        return(this) 
   } 

   # Return the linked list
   return(list(addNode = addNode)) 
}

